package com.nivor.file;import java.util.*;import org.springframework.data.domain.Page;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.EntityGraph;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Modifying;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;
public interface FileAssetRepository extends JpaRepository<FileAsset,Long>{@EntityGraph(attributePaths="project") @Query("select f from FileAsset f where f.user.id = :userId and (:query = '' or lower(f.originalName) like concat('%', :query, '%')) and (:category is null or lower(f.category) = lower(:category)) and (:projectId is null or f.project.id = :projectId) order by f.createdAt desc") Page<FileAsset> searchOwned(@Param("userId")long userId,@Param("query")String query,@Param("category")String category,@Param("projectId")Long projectId,Pageable pageable);Optional<FileAsset> findByIdAndUser_Id(Long id,Long userId);@Modifying @Query("update FileAsset f set f.project = null where f.project.id = :projectId and f.user.id = :userId") int clearProjectForUser(@Param("projectId")Long projectId,@Param("userId")Long userId);}
